import type {QueryClient} from '@tanstack/react-query'
// eslint-disable-next-line import/no-nodejs-modules
import {AsyncLocalStorage} from 'async_hooks'

import {createQueryClient, setServerQueryClientGetter} from './query-client'

// Re-export all of the query-client module's exports since this file will be the entry point for
// server-side usage of query-client
// eslint-disable-next-line no-barrel-files/no-barrel-files
export * from './query-client'

/**
 * AsyncLocalStorage for the per-request QueryClient context.
 * This ensures each request gets its own isolated QueryClient instance
 * to prevent data leakage between concurrent requests.
 */
const queryClientAsyncLocalStorage = new AsyncLocalStorage<QueryClient>()

/**
 * Run a function with a per-request QueryClient context.
 * This should be called at the server entry point to set up per-request isolation.
 *
 * @param fn - The function to run with the QueryClient context
 * @returns The result of the function
 */
export function runWithQueryClientContext<T>(fn: () => T): T {
  const queryClient = createQueryClient()
  return queryClientAsyncLocalStorage.run(queryClient, fn)
}

/**
 * Get the current QueryClient from the async local storage context.
 * This returns the per-request QueryClient instance that was set up
 * by runWithQueryClientContext.
 *
 * @returns The current request's QueryClient
 * @throws {Error} If not called within a QueryClient context
 */
export function getServerQueryClient(): QueryClient {
  const queryClient = queryClientAsyncLocalStorage.getStore()
  if (!queryClient) {
    throw new Error('getServerQueryClient() must be called within a QueryClient context')
  }
  return queryClient
}

// Automatically set up the server getter to use AsyncLocalStorage
setServerQueryClientGetter(() => {
  return getServerQueryClient()
})
