// eslint-disable-next-line import/no-nodejs-modules
import {AsyncLocalStorage} from 'async_hooks'
import {setServerEnvGetter, type ClientEnvironment} from './client-env'

// Re-export all of the client-env module's exports since this file will be the entry point for
// server-side usage of client-env
// eslint-disable-next-line no-barrel-files/no-barrel-files
export * from './client-env'

const envAsyncLocalStorage = new AsyncLocalStorage<ClientEnvironment>()

export function setClientEnvAsyncLocalStorage<T>(clientEnv: ClientEnvironment, fn: () => T) {
  return envAsyncLocalStorage.run(clientEnv, fn)
}

export function setCopilotApiOverrideUrl(copilotApiOverrideUrl: string | undefined) {
  const store = envAsyncLocalStorage.getStore()
  if (!store) return
  if (store.copilotApiOverrideUrl === copilotApiOverrideUrl) return

  store.copilotApiOverrideUrl = copilotApiOverrideUrl
}

setServerEnvGetter(() => {
  return envAsyncLocalStorage.getStore()
})
