// eslint-disable-next-line import/no-nodejs-modules
import {AsyncLocalStorage} from 'node:async_hooks'
import {setServerLocationGetter} from './ssr-globals'

// Re-export all of the ssr-globals module's exports since this file will be the entry point for
// server-side usage of ssr-globals
/**
 * Server-side entry point for `ssr-globals`.
 *
 * Use this module (e.g. `import * as SsrGlobals from './ssr-globals-server'`) from
 * server-only code such as SSR entry files or middleware so that server-specific
 * behavior (like AsyncLocalStorage-backed location handling) is available.
 *
 * For client-side code, import from the default `./ssr-globals` module instead to
 * avoid depending on Node.js-only APIs.
 */
export * from './ssr-globals'

// Server-side only async local storage for location
const locationStorage = new AsyncLocalStorage<URL>()

/**
 * Binds the provided URL to the current async execution context using AsyncLocalStorage
 * for the duration of the given callback.
 *
 * This should be called from server-side request handlers or middleware so that TSS
 * and other SSR utilities can reliably access the current request location, even
 * across asynchronous boundaries. The URL stored here is later read via the
 * `setServerLocationGetter` configured in this module.
 *
 * @typeParam T - The return type of the callback.
 * @param url - The request URL to associate with the current async context.
 * @param callback - A function to execute while the URL is set in AsyncLocalStorage.
 * @returns The value returned by the callback.
 */
export function setLocationAsyncLocalStorage<T>(url: URL, callback: () => T): T {
  return locationStorage.run(url, callback)
}

setServerLocationGetter(() => {
  return locationStorage.getStore()
})
