import {TransactionalMessageBanner} from '@github-ui/in-product-targeting'
import type {TransactionalMessageBanner as TransactionalMessageBannerType} from '@github-ui/code-view-types'

export interface IpmTransactionalMessageBannerPartialProps {
  banner: TransactionalMessageBannerType | null
}

export function IpmTransactionalMessageBannerPartial({banner}: IpmTransactionalMessageBannerPartialProps) {
  if (!banner) {
    return null
  }

  return <TransactionalMessageBanner banner={banner} />
}
