// eslint-disable-next-line import/no-nodejs-modules
import {AsyncLocalStorage} from 'async_hooks'

import {type ColorModeOptions, setServerColorModeGetter} from './use-color-modes'

// Re-export all of the use-color-modes module's exports since this file will be the entry point for
// server-side usage of color modes
// eslint-disable-next-line no-barrel-files/no-barrel-files
export * from './use-color-modes'

const colorModeAsyncLocalStorage = new AsyncLocalStorage<ColorModeOptions | undefined>()

export function setColorModeAsyncLocalStorage<T>(colorModeOptions: ColorModeOptions | undefined, fn: () => T) {
  return colorModeAsyncLocalStorage.run(colorModeOptions, fn)
}

setServerColorModeGetter(() => {
  return colorModeAsyncLocalStorage.getStore()
})
