/**
 * SSR shim for GSAP animation library
 *
 * GSAP creates a `gsapVersions` global when it initializes, which causes issues
 * in SSR environments. This shim provides no-op implementations of the gsap API.
 */

const noop = () => {}
// eslint-disable-next-line func-style
const noopReturnsThis = function (this: unknown) {
  return this
}

// Minimal gsap timeline-like object that supports method chaining
const createTimeline = (): GsapTimeline => {
  const timeline: GsapTimeline = {
    to: noopReturnsThis,
    from: noopReturnsThis,
    fromTo: noopReturnsThis,
    set: noopReturnsThis,
    call: noopReturnsThis,
    add: noopReturnsThis,
    addLabel: noopReturnsThis,
    addPause: noopReturnsThis,
    clear: noopReturnsThis,
    delay: noopReturnsThis,
    duration: noopReturnsThis,
    eventCallback: noopReturnsThis,
    endTime: () => 0,
    getById: () => null,
    getChildren: () => [],
    globalTime: () => 0,
    invalidate: noopReturnsThis,
    isActive: () => false,
    iteration: () => 0,
    kill: noopReturnsThis,
    pause: noopReturnsThis,
    paused: () => false,
    play: noopReturnsThis,
    progress: () => 0,
    recent: () => null,
    remove: noopReturnsThis,
    removeLabel: noopReturnsThis,
    removePause: noopReturnsThis,
    repeat: () => 0,
    repeatDelay: () => 0,
    restart: noopReturnsThis,
    resume: noopReturnsThis,
    reverse: noopReturnsThis,
    reversed: () => false,
    seek: noopReturnsThis,
    startTime: () => 0,
    then: () => Promise.resolve(),
    time: () => 0,
    timeScale: () => 1,
    totalDuration: () => 0,
    totalProgress: () => 0,
    totalTime: () => 0,
    tweenFromTo: noopReturnsThis,
    tweenTo: noopReturnsThis,
    yoyo: () => false,
  }
  return timeline
}

interface GsapTimeline {
  to: typeof noopReturnsThis
  from: typeof noopReturnsThis
  fromTo: typeof noopReturnsThis
  set: typeof noopReturnsThis
  call: typeof noopReturnsThis
  add: typeof noopReturnsThis
  addLabel: typeof noopReturnsThis
  addPause: typeof noopReturnsThis
  clear: typeof noopReturnsThis
  delay: typeof noopReturnsThis
  duration: typeof noopReturnsThis
  eventCallback: typeof noopReturnsThis
  endTime: () => number
  getById: () => null
  getChildren: () => []
  globalTime: () => number
  invalidate: typeof noopReturnsThis
  isActive: () => boolean
  iteration: () => number
  kill: typeof noopReturnsThis
  pause: typeof noopReturnsThis
  paused: () => boolean
  play: typeof noopReturnsThis
  progress: () => number
  recent: () => null
  remove: typeof noopReturnsThis
  removeLabel: typeof noopReturnsThis
  removePause: typeof noopReturnsThis
  repeat: () => number
  repeatDelay: () => number
  restart: typeof noopReturnsThis
  resume: typeof noopReturnsThis
  reverse: typeof noopReturnsThis
  reversed: () => boolean
  seek: typeof noopReturnsThis
  startTime: () => number
  then: () => Promise<void>
  time: () => number
  timeScale: () => number
  totalDuration: () => number
  totalProgress: () => number
  totalTime: () => number
  tweenFromTo: typeof noopReturnsThis
  tweenTo: typeof noopReturnsThis
  yoyo: () => boolean
}

// Main gsap object
export const gsap = {
  to: () => createTimeline(),
  from: () => createTimeline(),
  fromTo: () => createTimeline(),
  set: noop,
  timeline: () => createTimeline(),
  registerPlugin: noop,
  defaults: noop,
  config: noop,
  getProperty: () => 0,
  killTweensOf: noop,
  quickSetter: () => noop,
  quickTo: () => noop,
  ticker: {
    add: noop,
    remove: noop,
    fps: noop,
    deltaRatio: () => 1,
    frame: 0,
    time: 0,
    wake: noop,
    sleep: noop,
    lagSmoothing: noop,
  },
  utils: {
    checkPrefix: () => '',
    clamp: (min: number, max: number, value: number) => Math.min(max, Math.max(min, value)),
    distribute: () => noop,
    getUnit: () => '',
    interpolate: () => noop,
    mapRange: () => noop,
    normalize: () => 0,
    pipe: () => noop,
    random: (min: number, max: number) => min + Math.random() * (max - min),
    selector: () => () => [],
    shuffle: <T>(arr: T[]) => arr,
    snap: () => noop,
    splitColor: () => [0, 0, 0],
    toArray: <T>(value: T | T[]) => (Array.isArray(value) ? value : [value]),
    unitize: () => noop,
    wrap: () => noop,
    wrapYoyo: () => noop,
  },
  parseEase: () => noop,
  version: '0.0.0',
  effects: {},
  core: {
    globals: () => ({}),
    Tween: class {},
    Timeline: class {},
    Animation: class {},
    PropTween: class {},
  },
}

// Default export
export default gsap
