/**
 * Simple performance API shim for SSR environments (VMs) where the global
 * `performance` object may not be available and Node.js modules can't be imported.
 *
 * This provides a minimal implementation that won't break code that accesses
 * performance.now(), performance.mark(), etc.
 *
 * SSR does not need high-resolution timing, so we always use Date.now() for
 * simplicity.  This avoids a subtle circular reference: rspack's ProvidePlugin
 * injects *this file* as the `performance` global, so checking
 * `typeof performance` at evaluation time would see the shim itself on
 * subsequent requires rather than a real browser/Node performance API.
 */

const performanceShim = {
  now: () => Date.now(),
  mark: () => {},
  measure: () => {},
  clearMarks: () => {},
  clearMeasures: () => {},
  getEntries: () => [],
  getEntriesByName: () => [],
  getEntriesByType: () => [],
  timeOrigin: Date.now(),
}

// eslint-disable-next-line import/no-commonjs, no-undef
module.exports = performanceShim
