// Server-side sanitization using DOMPurify with a linkedom-backed DOM.
//
// The linkedom window and default DOMPurify instance are created once at
// module load time — before any request handling. This avoids per-request
// initialization overhead in the alloy VM.
//
// This file is resolved via the "node" condition in package.json exports,
// so it's only loaded in SSR/server builds — never shipped to the browser.

import {isFeatureEnabled} from '@github-ui/feature-flags'
// eslint-disable-next-line no-restricted-imports -- This IS the sanitize package.
import type {Config as DOMPurifyConfig, WindowLike} from 'dompurify'
// eslint-disable-next-line no-restricted-imports -- This IS the sanitize package.
import createDOMPurify from 'dompurify'
import {parseHTML} from 'linkedom'
import type {TrustedHTML} from 'trusted-types/lib/index'

import type {SafeHTMLString} from './safe-html-string'
import type {Purifier} from './types'

/**
 * Build a plain window-like object from linkedom for DOMPurify.
 *
 * linkedom's `parseHTML` returns a `defaultView` that is a Proxy around
 * globalThis — property assignments silently go to globalThis. We build
 * a plain object instead, with only the APIs DOMPurify needs.
 */
function createLinkedomWindow() {
  const linkedomWindow = parseHTML('')
  const doc = linkedomWindow.document as Document & Record<string, unknown>

  // Pre-create a single reusable document so DOMParser.parseFromString and
  // the createHTMLDocument/createDocument fallbacks avoid the cost of
  // parseHTML() — which constructs an entire linkedom window (Proxy-backed
  // defaultView, all DOM constructors, etc.) — on every sanitize() call.
  // Only the HTML re-parsing (body.innerHTML assignment) is repeated.
  // One document suffices because DOMPurify is synchronous and single-
  // threaded — the DOMParser path and fallback path are mutually exclusive
  // within _initDocument, and init calls complete before any sanitize().
  // NOTE: Do not call sanitize() reentrantly from a DOMPurify hook.
  const reusableDoc = parseHTML('<!DOCTYPE html><html><head></head><body></body></html>').document

  const w: WindowLike = {
    document: doc,
    DocumentFragment: linkedomWindow.DocumentFragment,
    HTMLTemplateElement: linkedomWindow.HTMLTemplateElement,
    Node: linkedomWindow.Node,
    Element: linkedomWindow.Element,
    NodeFilter: linkedomWindow.NodeFilter || {
      SHOW_ELEMENT: 1,
      SHOW_TEXT: 4,
      SHOW_COMMENT: 128,
      SHOW_PROCESSING_INSTRUCTION: 64,
      SHOW_CDATA_SECTION: 8,
      FILTER_ACCEPT: 1,
      FILTER_REJECT: 2,
      FILTER_SKIP: 3,
    },
    NamedNodeMap: linkedomWindow.NamedNodeMap,
    HTMLFormElement: linkedomWindow.HTMLFormElement,
    // SSR intentionally bypasses the github-sanitize Trusted Types policy:
    // DOMPurify's RETURN_TRUSTED_TYPE path is browser-only, and the rendered
    // HTML is later re-parsed and re-hydrated client-side where TT enforcement
    // applies. Leaving this undefined keeps DOMPurify on the plain-string path.
    trustedTypes: undefined,

    // linkedom's built-in DOMParser produces broken HTML when parsing
    // text/html — e.g. `<p>hello</p>` becomes `<p><head></head><body></body>hello</p>`.
    // We reuse a pre-created document and reset its body.innerHTML instead
    // of calling parseHTML() per call (which constructs a full linkedom window).
    DOMParser: class {
      parseFromString(html: string, type: DOMParserSupportedType) {
        if (type === 'text/html') {
          reusableDoc.head.textContent = ''
          reusableDoc.body.textContent = ''
          // eslint-disable-next-line @github-ui/github-monorepo/require-set-sanitized-inner-html -- internal linkedom parser shim used during sanitization, not a render sink
          reusableDoc.body.innerHTML = html
          return reusableDoc
        }
        // XML fallback — use linkedom's native DOMParser for non-HTML types
        const P = linkedomWindow.DOMParser as unknown as {new (): DOMParser}
        return new P().parseFromString(html, type)
      }
    },
  }

  // DOMPurify checks implementation.createHTMLDocument to set isSupported = true
  if (!doc.implementation || typeof doc.implementation.createHTMLDocument !== 'function') {
    // @ts-expect-error — implementation is readonly but linkedom doesn't set it
    doc.implementation = {
      createHTMLDocument(_title?: string) {
        // Called once at DOMPurify init for isSupported check.
        reusableDoc.head.textContent = ''
        reusableDoc.body.textContent = ''
        return reusableDoc
      },
      createDocument() {
        // Fallback path — only reached if DOMParser.parseFromString fails.
        reusableDoc.head.textContent = ''
        reusableDoc.body.textContent = ''
        return reusableDoc
      },
    }
  }

  // DOMPurify captures Element.prototype.remove and Element.prototype.cloneNode
  // via lookupGetter and calls them on ALL node types (Comment, Text, etc.).
  // linkedom's Element uses internal END/NEXT markers that CharacterData nodes
  // don't have — patch with try/catch fallbacks.
  const origRemove = w.Element.prototype.remove
  w.Element.prototype.remove = function (this: ChildNode) {
    try {
      origRemove.call(this)
    } catch {
      if (this.parentNode) {
        this.parentNode.removeChild(this)
      }
    }
  }

  const origCloneNode = w.Element.prototype.cloneNode
  w.Element.prototype.cloneNode = function (this: Node, deep?: boolean) {
    try {
      return origCloneNode.call(this, deep)
    } catch {
      let proto = Object.getPrototypeOf(this) as {cloneNode?: (deep?: boolean) => Node} | null
      while (proto) {
        const desc = Object.getOwnPropertyDescriptor(proto, 'cloneNode')
        if (desc && desc.value !== w.Element.prototype.cloneNode) {
          return (desc.value as (deep?: boolean) => Node).call(this, deep)
        }
        proto = Object.getPrototypeOf(proto) as {cloneNode?: (deep?: boolean) => Node} | null
      }
      throw new Error('cloneNode: no fallback found for node')
    }
  }

  return w
}

// ── Module-level initialization ──────────────────────────────────────────
// Created once when the module is first imported (at server startup / VM
// bundle execution), NOT during request handling.
const linkedomWindow = createLinkedomWindow()
const defaultInstance = createDOMPurify(linkedomWindow)

// Reentrancy guard — protects the shared reusableDoc from corruption.
// If a DOMPurify hook ever calls sanitize() again, the inner call would
// reset the document mid-sanitization, silently producing wrong output.
// This flag turns that into a loud error instead.
let isSanitizing = false

/**
 * Sanitize HTML using DOMPurify backed by linkedom.
 *
 * The linkedom window is shared across all calls. For simple sanitization,
 * a shared DOMPurify instance is reused.
 *
 * @param html - The HTML string to sanitize
 * @param config - Optional DOMPurify Config object.
 */
export function sanitize(dirty: string | Node, cfg: DOMPurifyConfig & {RETURN_DOM: true}): Node
export function sanitize(dirty: string | Node, cfg: DOMPurifyConfig & {RETURN_DOM_FRAGMENT: true}): DocumentFragment
export function sanitize(dirty: string | Node, cfg: DOMPurifyConfig & {RETURN_TRUSTED_TYPE: true}): TrustedHTML
export function sanitize(dirty: string | Node, cfg: DOMPurifyConfig & {RETURN_TRUSTED_TYPE: false}): SafeHTMLString
export function sanitize(dirty: string | Node, cfg?: DOMPurifyConfig): SafeHTMLString
export function sanitize(
  dirty: string | Node,
  cfg?: DOMPurifyConfig,
): SafeHTMLString | Node | DocumentFragment | TrustedHTML {
  // sanitize() is sanitizeWithPurifier() bound to the module-level default instance.
  return sanitizeWithPurifier(dirty, defaultInstance as unknown as Purifier, cfg)
}

/**
 * Create a DOMPurify instance for advanced usage (e.g., adding hooks).
 * The returned purifier's `.sanitize()` is typed to return `SafeHTMLString`
 * for standard string sanitization calls.
 */
export function createPurifier(cb?: (purifier: Purifier) => void): Purifier {
  const purifier = createDOMPurify(linkedomWindow) as unknown as Purifier
  if (cb) {
    cb(purifier)
  }

  // Wrap .sanitize() to clone RETURN_DOM results (see sanitize() above).
  const origSanitize = purifier.sanitize.bind(purifier)
  purifier.sanitize = ((...args: Parameters<Purifier['sanitize']>) => {
    const [dirty, config] = args
    if (config?.RETURN_DOM && !config.RETURN_DOM_FRAGMENT) {
      const result = origSanitize(dirty, config)
      return (result as unknown as Node).cloneNode(true)
    }
    return origSanitize(dirty, config)
  }) as Purifier['sanitize']

  return purifier
}

export function sanitizeWithPurifier(
  dirty: string | Node,
  purifier: Purifier,
  cfg: DOMPurifyConfig & {RETURN_DOM: true},
): Node
export function sanitizeWithPurifier(
  dirty: string | Node,
  purifier: Purifier,
  cfg: DOMPurifyConfig & {RETURN_DOM_FRAGMENT: true},
): DocumentFragment
export function sanitizeWithPurifier(
  dirty: string | Node,
  purifier: Purifier,
  cfg: DOMPurifyConfig & {RETURN_TRUSTED_TYPE: true},
): TrustedHTML
export function sanitizeWithPurifier(
  dirty: string | Node,
  purifier: Purifier,
  cfg: DOMPurifyConfig & {RETURN_TRUSTED_TYPE: false},
): SafeHTMLString
export function sanitizeWithPurifier(dirty: string | Node, purifier: Purifier, cfg?: DOMPurifyConfig): SafeHTMLString
export function sanitizeWithPurifier(
  dirty: string | Node,
  purifier: Purifier,
  cfg?: DOMPurifyConfig,
): SafeHTMLString | Node | DocumentFragment | TrustedHTML {
  if (isSanitizing) {
    throw new Error(
      'sanitizeWithPurifier(): reentrant call detected. Do not call sanitize() from within a DOMPurify hook — ' +
        'the shared linkedom document would be corrupted.',
    )
  }
  isSanitizing = true
  try {
    // TODO: When hardening is implemented (#1724, #1725), this flag will gate
    // the DOMPurify hooks that strip js-* classes and block data-* attributes.
    const _hardeningEnabled = isFeatureEnabled('sanitize_dompurify_hardening')
    if (cfg?.RETURN_DOM && !cfg.RETURN_DOM_FRAGMENT) {
      // DOMPurify returns the live reusableDoc body — clone it so callers don't
      // accidentally share/mutate the same Node across calls.
      const domResult = purifier.sanitize(dirty, cfg) as unknown as Node
      return domResult.cloneNode(true)
    }
    return purifier.sanitize(dirty, cfg)
  } finally {
    isSanitizing = false
  }
}

// eslint-disable-next-line no-barrel-files/no-barrel-files
export type {Config, Purifier, UponSanitizeAttributeHookEvent} from './types'
