import {BudgetThresholdBanner} from '@github-ui/in-product-targeting'
import type {BudgetThresholdBannerProps} from '@github-ui/in-product-targeting'

export function IpmBudgetThresholdBannerPartial({banner, ctaHref, analytics, rounded}: BudgetThresholdBannerProps) {
  if (!banner?.text) {
    return null
  }

  return <BudgetThresholdBanner banner={banner} ctaHref={ctaHref} analytics={analytics} rounded={rounded} />
}
