/**
 * After `createStaticHandler.query()` completes, loader errors are captured in
 * `ctx.errors` instead of being propagated. This helper re-throws fatal SSR
 * errors that indicate a programming mistake (e.g. missing embedded data for
 * blocking queries). These errors produce meaningless SSR output, so we fail
 * hard rather than silently rendering an error boundary.
 *
 * Other loader errors (e.g. 404s, permission failures) are left for the
 * route's ErrorBoundary to handle — that's valid SSR output that hydrates
 * correctly on the client.
 *
 * We may later determine other errors should also propagate as fatal SSR errors.
 */
function assertNoSSRFatalErrors(ctx: {errors?: Record<string, unknown> | null}) {
  if (!ctx.errors) return
  for (const error of Object.values(ctx.errors)) {
    if (error instanceof MissingSSREmbeddedDataError) {
      throw error
    }
  }
}

function assertNoTanStackSSRFatalErrors(matches: Array<{error: unknown}>) {
  for (const match of matches) {
    if ('status' in match && match.status === 'redirected') {
      throw new Error('Loader redirects via throwing a Response is not currently supported.')
    }
    if (match.error instanceof MissingSSREmbeddedDataError) {
      throw match.error
    }
  }
}

interface BaseRequest {
  name: string
  url: string
  clientEnv: ClientEnvironment
  colorModes: ColorModeOptions
  data_router_enabled?: boolean
}

export interface AppRenderRequest extends BaseRequest {
  path: string
  data: EmbeddedData
}

export interface PartialRenderRequest extends BaseRequest {
  data: EmbeddedPartialData
}

/**
 * Maps dynamic chunk names to their associated CSS and JS asset filenames.
 * Produced by the rspack build as `dynamic-chunk-map.json`.
 * The Alloy Go server reads this file and passes it into the request.
 */
export interface DynamicChunkMap {
  [chunkName: string]: {css: string[]; js: string[]}
}

export interface FullDocumentRenderRequest extends BaseRequest {
  data: EmbeddedData
  path: string
  scripts: string
  stylesheets: string
  /** Optional: chunk name → {css, js} map from dynamic-chunk-map.json */
  dynamicChunkMap?: DynamicChunkMap
  /** CDN / asset prefix for resolving filenames to URLs (e.g. "/assets/") */
  assetPrefix?: string
}

function getLocationPartsFromPath(path: string) {
  const {pathname, search, hash} = new URL(
    path,
    // we fallback to github.com, if a location is not set, but this shouldn't be relied on
    ssrSafeLocation.origin || 'https://github.com',
  )
  return {
    pathname,
    search,
    hash,
  } as const
}

async function getDataRouterAppEntry({
  app,
  path,
  name,
  data,
}: {
  app: DataRouterAppRegistrationObject
  name: string
  path: string
  data: EmbeddedData
}) {
  const {routes} = app.registration({embeddedData: data})

  if (isTanStackRouterEnabled(app.tanStackRouterEnabled)) {
    return getTanStackRouterAppEntry({routes, name, path, data})
  }

  const routesWithSharedProviders = routesWithProviders(routes, {
    appPayload: data.appPayload,
    ssrError: undefined,
    appName: name,
    dataRouterEnabled: true,
  })

  // Preload dynamic components for matched routes before rendering
  const {pathname} = getLocationPartsFromPath(path)
  await preloadMatchedDataRouterComponents(routes, pathname)

  const {dataRoutes, query} = createStaticHandler(routesWithSharedProviders, {})
  const ctx = await query(new Request(new URL(path, ssrSafeLocation.origin || 'https://github.com')))

  if (!('matches' in ctx)) {
    // If `query` returns a Response, we should redirect instead - this would be a loader redirecting
    // We don't support this, as we should redirect in rails directly
    throw new Error('Loader redirects via throwing a Response is not currently supported.')
  }

  assertNoSSRFatalErrors(ctx)

  const router = createStaticRouter(dataRoutes, ctx)

  return <StaticRouterProvider router={router} context={ctx} hydrate={false} />
}

async function getTanStackRouterAppEntry({
  routes,
  name,
  path,
  data,
}: {
  routes: ReturnType<DataRouterAppRegistrationObject['registration']>['routes']
  name: string
  path: string
  data: EmbeddedData
}) {
  const {pathname, search, hash} = getLocationPartsFromPath(path)
  const history = createTanStackMemoryHistory({initialEntries: [`${pathname}${search}${hash}` || '/']})
  const queryClient = getQueryClient()
  const router = tanStackRouterWithProviders(routes, {
    appPayload: data.appPayload,
    ssrError: undefined,
    appName: name,
    context: {embeddedData: data, queryClient},
    history,
  })

  await router.load()
  assertNoTanStackSSRFatalErrors(router.state.matches)

  return <TanStackRouterServer router={router} />
}

async function getAppEntry({name, path, data, data_router_enabled}: AppRenderRequest) {
  if (data_router_enabled) {
    const app = reactDataRouterAppSyncRegistry.get(name)
    if (!app) {
      throw new Error(`Unknown data router app ${name}`)
    }
    return getDataRouterAppEntry({app, name, path, data})
  }

  const app = reactNavigatorAppSyncRegistry.get(name)
  if (!app) {
    throw new Error(`Unknown navigator app ${name}`)
  }

  const {App, routes} = app.registration()

  // Initial path is set by ruby. Fragments are not sent to the server.
  const {pathname, search, hash} = getLocationPartsFromPath(path)
  const history = createMemoryHistory({initialEntries: [{pathname, search, hash}]})

  const {key, state} = history.location
  const initialLocation = {
    pathname,
    search,
    hash,
    key,
    state,
  }

  await preloadMatchedRouteComponents(routes, initialLocation)

  return (
    <NavigatorServerEntry
      appName={name}
      embeddedData={data}
      routes={routes}
      App={App}
      initialLocation={initialLocation}
    />
  )
}

async function getAppEntryWithAppShellLayout({name, path, data}: FullDocumentRenderRequest) {
  const app = reactDataRouterAppSyncRegistry.get(name)
  if (!app) {
    throw new Error(`Unknown data router app ${name}`)
  }
  const appShellApp = reactDataRouterAppSyncRegistry.get('app-shell')
  if (!appShellApp) {
    throw new Error(`Unknown data router app app-shell`)
  }

  // Get the app routes:
  const register = app.registration({embeddedData: data})
  let routes = register.routes

  // Get the app shell routes:
  const {routes: appShellRoutes} = appShellApp.registration({embeddedData: data})

  // Wrap the app shell routes around the app routes:
  if (appShellRoutes.length !== 1) {
    throw new Error('Expected app shell routes to have a single entry')
  }
  const [appShellRouteObject] = appShellRoutes
  routes = [{...appShellRouteObject, children: routes, index: false}]

  if (isTanStackRouterEnabled(app.tanStackRouterEnabled)) {
    return getTanStackRouterAppEntry({routes, name, path, data})
  }

  // Wrap the routes with providers:
  routes = routesWithProviders(routes, {
    appPayload: data.appPayload,
    ssrError: undefined,
    appName: name,
    dataRouterEnabled: true,
  })

  // Preload dynamic components for matched routes before rendering
  const {pathname} = getLocationPartsFromPath(path)
  await preloadMatchedDataRouterComponents(register.routes, pathname)

  const {dataRoutes, query} = createStaticHandler(routes, {})
  const ctx = await query(new Request(new URL(path, ssrSafeLocation.origin || 'https://github.com')))

  if (!('matches' in ctx)) {
    // If `query` returns a Response, we should redirect instead - this would be a loader redirecting
    // We don't support this, as we should redirect in rails directly
    throw new Error('Loader redirects via throwing a Response is not currently supported.')
  }

  assertNoSSRFatalErrors(ctx)

  const router = createStaticRouter(dataRoutes, ctx)

  return <StaticRouterProvider router={router} context={ctx} hydrate={false} />
}

function getPartialEntry({name, data}: PartialRenderRequest, url: string) {
  const partial = reactPartials.get(name)

  if (!partial) {
    throw new Error(`Unknown partial ${name}`)
  }

  const {pathname, search, hash} = getLocationPartsFromPath(url)
  const {Component} = partial

  return (
    <PartialEntry partialName={name}>
      <StaticRouter location={{pathname, search, hash}}>
        <Routes>
          <Route path="*" element={<Component {...data.props} />} />
        </Routes>
      </StaticRouter>
    </PartialEntry>
  )
}

/**
 * Structured result returned by SSR handlers.
 * `dynamicChunks` lists the chunk names rendered during SSR so that
 * the caller (Alloy → Rails) can resolve them to CSS/JS asset URLs
 * without parsing HTML comments.
 */
export interface SSRResult {
  html: string
  dynamicChunks?: string[]
}

export async function handleRequest(
  request: AppRenderRequest | PartialRenderRequest | FullDocumentRenderRequest,
): Promise<SSRResult> {
  // Ensure the correct color mode options are applied
  const {colorModes, url} = request

  return runWithQueryClientContext(() => {
    return setColorModeAsyncLocalStorage(colorModes, () => {
      // eslint-disable-next-line no-restricted-syntax
      return setLocationAsyncLocalStorage(new URL(url), () => {
        return setClientEnvAsyncLocalStorage(request.clientEnv, async () => {
          if ('scripts' in request) {
            // Full-document renders resolve dynamic chunks to inline <link>/<script>
            // tags, so no structured chunk list is needed.
            const html = await handleFullDocumentRenderRequest(request)
            return {html}
          } else {
            return handleElementRenderRequest(request)
          }
        })
      })
    })
  })
}

export async function handleElementRenderRequest(request: AppRenderRequest | PartialRenderRequest): Promise<SSRResult> {
  // Get the entry node, based on the request type
  const entry = 'path' in request ? await getAppEntry(request) : getPartialEntry(request, request.url)

  // Render the entry node with stylesheets + dynamic chunk collection.
  // Use try/finally to ensure the collector is always reset — avoids leaking
  // chunk names across requests if alloy ever pools worker contexts.
  const sheet = new ServerStyleSheet()
  const chunkCollector = new DynamicChunkCollector()
  try {
    const markup = renderToString(
      sheet.collectStyles(<DynamicChunkProvider collector={chunkCollector}>{entry}</DynamicChunkProvider>),
    )

    const dynamicChunks = chunkCollector.getChunks()

    // Return the rendered markup with stylesheets + structured chunk list
    return {
      html: `${sheet.getStyleTags()}${markup}`,
      dynamicChunks: dynamicChunks.length > 0 ? dynamicChunks : undefined,
    }
  } finally {
    sheet.seal()
    chunkCollector.reset()
  }
}

export async function handleFullDocumentRenderRequest(request: FullDocumentRenderRequest) {
  const {name, data} = request
  const embeddedDataStringified = JSON.stringify(data).replace(/</g, '\\u003c')
  const appEntry = await getAppEntryWithAppShellLayout(request)
  const chunkCollector = new DynamicChunkCollector()
  let reactMarkup: string
  let dynamicAssetTags: DynamicAssetTags
  try {
    reactMarkup = renderToString(<DynamicChunkProvider collector={chunkCollector}>{appEntry}</DynamicChunkProvider>)
    dynamicAssetTags = buildDynamicAssetTags(chunkCollector, request.dynamicChunkMap, request.assetPrefix)
  } finally {
    chunkCollector.reset()
  }

  // TODO: this HTML template is missing a lot of the functionality of our Rails layouts, and is only here as a
  // temporary way to bootstrap a "full document" SSR.
  return `<!DOCTYPE html>
<html lang="en" data-color-mode="auto" data-light-theme="light" data-dark-theme="dark">
<head>
  ${request.stylesheets}
  ${dynamicAssetTags.stylesheets}
  ${request.scripts}
  ${dynamicAssetTags.modulePreloads}
  <meta charSet="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
</head>
<body>
  <react-app app-name="${name}" initial-path="${encodeURIComponent(
    request.path,
  )}"style="display: block; min-height: calc(100vh - 64px);" data-attempted-ssr="true" data-ssr="false" data-lazy="false" data-alternate="false" data-data-router-enabled="true" data-react-profiling="false" data-app-shell="true">
    <script type="application/json" data-target="react-app.embeddedData">
      ${embeddedDataStringified}
    </script>
    <div data-target="react-app.reactRoot">
      ${reactMarkup}
    </div>
  </react-app>
  ${dynamicAssetTags.scripts}
</body>
</html>`
}

interface DynamicAssetTags {
  /** <link rel="stylesheet"> tags for dynamic CSS */
  stylesheets: string
  /** <link rel="modulepreload"> tags for dynamic JS chunks */
  modulePreloads: string
  /** <script type="module"> tags placed before </body> */
  scripts: string
}

const EMPTY_ASSET_TAGS: DynamicAssetTags = {stylesheets: '', modulePreloads: '', scripts: ''}

/**
 * Resolve rendered dynamic chunks to <link> and <script> tags for the full-doc path.
 *
 * When the Alloy Go server provides `dynamicChunkMap` (from dynamic-chunk-map.json),
 * we can emit asset tags directly — no round-trip to Rails needed.
 *
 * - CSS  → `<link rel="stylesheet">` in <head> (prevents FOUC)
 * - JS   → `<link rel="modulepreload">` in <head> (warms browser cache)
 *          + `<script type="module">` before </body> (starts execution)
 */
function buildDynamicAssetTags(
  collector: DynamicChunkCollector,
  chunkMap?: DynamicChunkMap,
  assetPrefix = '/assets/',
): DynamicAssetTags {
  const chunks = collector.getChunks()
  if (chunks.length === 0 || !chunkMap) return EMPTY_ASSET_TAGS

  const seenCss = new Set<string>()
  const seenJs = new Set<string>()
  const cssFiles: string[] = []
  const jsFiles: string[] = []

  for (const chunkName of chunks) {
    const entry = chunkMap[chunkName]
    if (!entry) continue
    for (const css of entry.css) {
      if (!seenCss.has(css)) {
        seenCss.add(css)
        cssFiles.push(css)
      }
    }
    for (const js of entry.js) {
      if (!seenJs.has(js)) {
        seenJs.add(js)
        jsFiles.push(js)
      }
    }
  }

  const prefix = assetPrefix.endsWith('/') ? assetPrefix : `${assetPrefix}/`

  const stylesheets = cssFiles
    // eslint-disable-next-line github/unescaped-html-literal -- trusted build-time asset filenames, not user input
    .map(f => `<link rel="stylesheet" href="${prefix}${f}" data-dynamic-css fetchpriority="high" />`)
    .join('\n  ')

  // eslint-disable-next-line github/unescaped-html-literal -- trusted build-time asset filenames, not user input
  const modulePreloads = jsFiles.map(f => `<link rel="modulepreload" href="${prefix}${f}" />`).join('\n  ')

  // eslint-disable-next-line github/unescaped-html-literal -- trusted build-time asset filenames, not user input
  const scripts = jsFiles.map(f => `<script type="module" src="${prefix}${f}" async></script>`).join('\n  ')

  return {stylesheets, modulePreloads, scripts}
}

declare global {
  function handleRequest(
    request: AppRenderRequest | PartialRenderRequest | FullDocumentRenderRequest,
  ): Promise<SSRResult>
}
